#!/bin/bash
# publish_pages.sh — publish an Ad Hoc IPA and the OTA install page.
#
# Inputs: <version> <path-to-ipa>
# Env:    HSCC_BUNDLE_PREFIX (default ro.parsec.hscc — the shipped identity)
#         HSCC_REPO (default pom11/hscc)
#         HSCC_RELEASE_TAG (default apps-v<version>)
#         HSCC_BUILD_NUMBER (default apps/BUILD_NUMBER)
#         HSCC_RELEASE_NOTES_FILE (rendered markdown; generated by release_apps.sh)
#
# What lands where:
#   * GitHub release `apps-v<version>` on pom11/hscc, asset HSCC-<version>.ipa.
#     It is explicitly NOT the repository's "latest" release, so it never
#     shadows the CLI releases. The macOS zip lands on the SAME release.
#   * branch `gh-pages`, only under /ios/ (plus a root .nojekyll):
#       ios/index.html          install button + version + What's new + history
#       ios/manifest.plist      Apple OTA manifest for the CURRENT build
#       ios/manifests/<ver>.plist   versioned archive of every manifest
#       ios/version.json        feed for the in-app update check
#       ios/releases.json       release history used by the page
#       ios/notes/<ver>.html    permanent release notes
#       ios/icons/icon-{57,512,1024}.png
#     An existing gh-pages branch is preserved and only those files are
#     committed. A missing branch is created as an orphan with only the site.
#   * GitHub Pages enabled from gh-pages via `gh api`, idempotently.
#
# The IPA itself is never committed to the branch; the manifest points at the
# release asset over HTTPS, which is what iOS downloads.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
IOS_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
REPO_ROOT="$(cd "$IOS_DIR/.." && pwd)"

VERSION="${1:-}"
IPA="${2:-}"
if [ -z "$VERSION" ] || [ -z "$IPA" ]; then
  echo "usage: $0 <version> <path-to-ipa>" >&2
  exit 2
fi
if ! printf '%s' "$VERSION" | grep -Eq '^[0-9]+(\.[0-9]+){1,2}$'; then
  echo "error: version must look like 1.2.3: $VERSION" >&2
  exit 2
fi
[ -f "$IPA" ] || { echo "error: IPA not found: $IPA" >&2; exit 1; }

REPO="${HSCC_REPO:-pom11/hscc}"
OWNER="${REPO%%/*}"
NAME="${REPO##*/}"
PAGES_BASE="https://${OWNER}.github.io/${NAME}"
PREFIX="${HSCC_BUNDLE_PREFIX:-ro.parsec.hscc}"
BUNDLE_ID="${HSCC_BUNDLE_ID:-${PREFIX}.ios}"
TAG="${HSCC_RELEASE_TAG:-apps-v${VERSION}}"
BUILD="${HSCC_BUILD_NUMBER:-$(cat "$REPO_ROOT/apps/BUILD_NUMBER" 2>/dev/null || echo 1)}"
NOTES_FILE="${HSCC_RELEASE_NOTES_FILE:-}"
ASSET="HSCC-${VERSION}.ipa"
IPA_URL="https://github.com/${REPO}/releases/download/${TAG}/${ASSET}"
ICON57_URL="${PAGES_BASE}/ios/icons/icon-57.png"
ICON512_URL="${PAGES_BASE}/ios/icons/icon-512.png"
MANIFEST_URL="${PAGES_BASE}/ios/manifest.plist"

for tool in gh git python3 sips unzip; do
  command -v "$tool" >/dev/null 2>&1 || { echo "error: $tool not found" >&2; exit 1; }
done
gh auth status >/dev/null 2>&1 || { echo "error: gh is not authenticated. Run: gh auth login" >&2; exit 1; }

step() { echo ""; echo "==> $*"; }

step "Upload the IPA to GitHub release $TAG (not latest)"
notes_args=(--notes "Ad Hoc iOS build $VERSION. Install from ${PAGES_BASE}/ios/ on a registered iPhone (Safari).")
if [ -n "$NOTES_FILE" ] && [ -f "$NOTES_FILE" ]; then
  notes_args=(--notes-file "$NOTES_FILE")
fi
if gh release view "$TAG" --repo "$REPO" >/dev/null 2>&1; then
  gh release upload "$TAG" "$IPA#$ASSET" --repo "$REPO" --clobber
  gh release edit "$TAG" --repo "$REPO" --latest=false "${notes_args[@]}"
else
  gh release create "$TAG" "$IPA#$ASSET" \
    --repo "$REPO" \
    --title "HSCC apps $VERSION" \
    "${notes_args[@]}" \
    --latest=false
fi
echo "    asset: $IPA_URL"

step "Prepare the gh-pages worktree"
PAGES_DIR="$(mktemp -d "${TMPDIR:-/tmp}/hscc-pages.XXXXXX")/gh-pages"
TMP_BRANCH=""
cleanup() {
  git -C "$REPO_ROOT" worktree remove --force "$PAGES_DIR" >/dev/null 2>&1 \
    || rm -rf "$(dirname "${PAGES_DIR:-}")"
  # The orphan path below needs a branch to be unborn on; it is throwaway, so
  # it is deleted here rather than left behind in the shared repository.
  if [ -n "$TMP_BRANCH" ]; then
    git -C "$REPO_ROOT" branch -D "$TMP_BRANCH" >/dev/null 2>&1 || true
  fi
}
trap cleanup EXIT

# Both git calls are pinned to $REPO_ROOT with -C, and they must stay that way.
# A bare `git ls-remote origin` / `git fetch origin` resolves the remote and
# writes FETCH_HEAD in whichever repo owns the CURRENT WORKING DIRECTORY, which
# is this repo only when the release happened to be run from inside it. From
# anywhere else the branch check answers about someone else's remote and the
# worktree below either cannot resolve FETCH_HEAD at all or, worse, resolves an
# unrelated FETCH_HEAD and pushes the wrong commit onto the branch that serves
# the install page.
if git -C "$REPO_ROOT" ls-remote --exit-code --heads origin gh-pages >/dev/null 2>&1; then
  git -C "$REPO_ROOT" fetch --quiet origin gh-pages
  # Detached on purpose: the push below is HEAD:gh-pages, so no local branch
  # named gh-pages is needed — and a `checkout -B gh-pages` would reset, or
  # fail on, a gh-pages branch that another worktree already has checked out.
  git -C "$REPO_ROOT" worktree add --quiet --detach "$PAGES_DIR" FETCH_HEAD
  echo "    reusing existing gh-pages (site files preserved)"
else
  git -C "$REPO_ROOT" worktree add --quiet --detach "$PAGES_DIR" HEAD
  # A unique name, because the repository can already hold a local gh-pages
  # branch that has nothing to do with this remote branch; `--orphan gh-pages`
  # would then die with "a branch named 'gh-pages' already exists".
  TMP_BRANCH="hscc-ios-publish-$$-${RANDOM}"
  git -C "$PAGES_DIR" checkout --quiet --orphan "$TMP_BRANCH"
  git -C "$PAGES_DIR" rm -rf . >/dev/null
  echo "    creating orphan gh-pages (site files only)"
fi
# Pages ignores files/dirs starting with an underscore; this is the standard
# opt-out for a hand-built site.
mkdir -p "$PAGES_DIR/ios/icons" "$PAGES_DIR/ios/manifests" "$PAGES_DIR/ios/notes"
: > "$PAGES_DIR/.nojekyll"

step "Generate the OTA manifest and icons"
SOURCE_ICON="$IOS_DIR/Assets.xcassets/AppIcon.appiconset/AppIcon.png"
[ -f "$SOURCE_ICON" ] || { echo "error: missing $SOURCE_ICON (run scripts/make_appicon.sh)" >&2; exit 1; }
cp "$SOURCE_ICON" "$PAGES_DIR/ios/icons/icon-1024.png"
sips -z 57 57 "$SOURCE_ICON" --out "$PAGES_DIR/ios/icons/icon-57.png" >/dev/null
sips -z 512 512 "$SOURCE_ICON" --out "$PAGES_DIR/ios/icons/icon-512.png" >/dev/null

python3 "$SCRIPT_DIR/make_manifest.py" \
  --bundle-id "$BUNDLE_ID" \
  --version "$BUILD" \
  --ipa-url "$IPA_URL" \
  --icon-57-url "$ICON57_URL" \
  --icon-512-url "$ICON512_URL" \
  --title "HSCC" \
  --out "$PAGES_DIR/ios/manifest.plist"
# Keep every published manifest so an older build can still be audited.
cp "$PAGES_DIR/ios/manifest.plist" "$PAGES_DIR/ios/manifests/${VERSION}.plist"

step "Render the install page, release notes and version.json"
if [ -n "$NOTES_FILE" ] && [ -f "$NOTES_FILE" ]; then
  python3 "$REPO_ROOT/scripts/apps_release.py" publish-ios \
    --pages-dir "$PAGES_DIR" --ios-dir "$IOS_DIR" \
    --version "$VERSION" --build "$BUILD" --notes-md "$NOTES_FILE" \
    --bundle-id "$BUNDLE_ID" --ipa-url "$IPA_URL"
else
  python3 "$REPO_ROOT/scripts/apps_release.py" publish-ios \
    --pages-dir "$PAGES_DIR" --ios-dir "$IOS_DIR" \
    --version "$VERSION" --build "$BUILD" \
    --bundle-id "$BUNDLE_ID" --ipa-url "$IPA_URL"
fi

step "Commit and push gh-pages (site files only)"
git -C "$PAGES_DIR" add .nojekyll ios
if git -C "$PAGES_DIR" diff --cached --quiet; then
  echo "    no change to publish"
else
  git -C "$PAGES_DIR" -c user.name="HSCC release" \
    -c user.email="release@users.noreply.github.com" \
    commit --quiet -m "ios: publish HSCC ${VERSION}"
  git -C "$PAGES_DIR" push --quiet origin HEAD:gh-pages
  echo "    pushed $(git -C "$PAGES_DIR" rev-parse --short HEAD) to gh-pages"
fi

step "Enable GitHub Pages from gh-pages (idempotent)"
PAGES_API="repos/${REPO}/pages"
PAGES_BODY='{"build_type":"legacy","source":{"branch":"gh-pages","path":"/"}}'
if gh api "$PAGES_API" >/dev/null 2>&1; then
  printf '%s' "$PAGES_BODY" | gh api --method PUT "$PAGES_API" --input - >/dev/null
  echo "    Pages already enabled; source set to gh-pages"
else
  # A first push to gh-pages can enable Pages on its own a moment later, so
  # the POST may answer 409 "already enabled"; re-read before calling it fatal.
  if printf '%s' '{"source":{"branch":"gh-pages","path":"/"}}' \
      | gh api --method POST "$PAGES_API" --input - >/dev/null 2>&1; then
    echo "    Pages enabled from gh-pages"
  elif gh api "$PAGES_API" >/dev/null 2>&1; then
    echo "    Pages was enabled meanwhile (push-triggered); source is gh-pages"
  else
    echo "error: could not enable GitHub Pages on $REPO" >&2
    exit 1
  fi
fi

step "Published"
echo "    install page: $PAGES_BASE/ios/"
echo "    notes:        $PAGES_BASE/ios/notes/${VERSION}.html"
echo "    version.json: $PAGES_BASE/ios/version.json"
echo "    manifest:     $MANIFEST_URL"
echo "    release:      https://github.com/${REPO}/releases/tag/${TAG}"
echo "    GitHub may take a minute to build the Pages site."
